export default {
  fetch(request) {
    const path = new URL(request.url).pathname;
    if (path === '/mcp') return serveMcp(request, 'bichum', 'bichum.aldol.app');
    const headers = new Headers({
      'X-Content-Type-Options': 'nosniff',
      'Referrer-Policy': 'strict-origin-when-cross-origin',
      'Content-Security-Policy': "default-src 'none'; style-src 'self'; img-src 'self'; script-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'",
      'Strict-Transport-Security': 'max-age=31536000',
      'X-Studio-Site': 'bichum',
    });
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      headers.set('Allow', 'GET, HEAD');
      return new Response('Method not allowed', { status: 405, headers });
    }

    if (path === '/tools/') return Response.redirect(new URL('/tools', request.url), 308);
    if (!Object.hasOwn(routes, path)) {
      return new Response(request.method === 'HEAD' ? null : '페이지를 찾을 수 없어요.', { status: 404, headers });
    }

    const { type, cache, body, binary } = routes[path];
    headers.set('Content-Type', type);
    headers.set('Cache-Control', cache);
    const content = request.method === 'HEAD' ? null : binary
      ? Uint8Array.from(atob(body), (value) => value.charCodeAt(0))
      : body;
    return new Response(content, { headers });
  },
};